ALTER TABLE "User" ADD COLUMN "telegramId" BIGINT UNIQUE, ADD COLUMN "telegramVerifiedAt" TIMESTAMPTZ(3);
ALTER TABLE "User" ADD CONSTRAINT telegram_identity CHECK(("telegramId" IS NULL AND "telegramVerifiedAt" IS NULL) OR ("telegramId">0 AND "telegramVerifiedAt" IS NOT NULL AND kind='CUSTOMER'));
CREATE TABLE "StoreSettings"(id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), "telegramEnabled" BOOLEAN NOT NULL DEFAULT false, "botUsername" VARCHAR(32) NOT NULL DEFAULT 'kiyaco24bot', "botTokenEncrypted" TEXT, "webhookSecretEncrypted" TEXT, "cardEnabled" BOOLEAN NOT NULL DEFAULT false, "bankName" VARCHAR(80) NOT NULL DEFAULT '', "cardNumber" VARCHAR(16) NOT NULL DEFAULT '', "cardHolder" VARCHAR(100) NOT NULL DEFAULT '', "shippingToman" DECIMAL(14,0) NOT NULL DEFAULT 0 CHECK("shippingToman">=0), "taxToman" DECIMAL(14,0) NOT NULL DEFAULT 0 CHECK("taxToman">=0), "transferMinutes" INTEGER NOT NULL DEFAULT 60 CHECK("transferMinutes" BETWEEN 15 AND 1440), "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE "TelegramLogin"(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),"selectorHash" VARCHAR(64) NOT NULL UNIQUE,"browserHash" VARCHAR(64) NOT NULL,"displayCode" VARCHAR(8) NOT NULL,"telegramId" BIGINT,"displayName" VARCHAR(80),"approvedAt" TIMESTAMPTZ(3),"consumedAt" TIMESTAMPTZ(3),"expiresAt" TIMESTAMPTZ(3) NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),CHECK("expiresAt">"createdAt"),CHECK("approvedAt" IS NULL OR "telegramId">0),CHECK("consumedAt" IS NULL OR "approvedAt" IS NOT NULL));
CREATE INDEX "TelegramLogin_expiresAt_idx" ON "TelegramLogin"("expiresAt");
CREATE TABLE "TelegramUpdate"(id BIGINT PRIMARY KEY,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE "TelegramOutbox"(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),"chatId" BIGINT NOT NULL,text VARCHAR(1000) NOT NULL,callback VARCHAR(64),state VARCHAR(12) NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','SENDING','SENT','UNKNOWN')),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now());
